PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "__drizzle_migrations" (
			id SERIAL PRIMARY KEY,
			hash text NOT NULL,
			created_at numeric
		);
CREATE TABLE entries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  text TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE TABLE parts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  sku TEXT NOT NULL DEFAULT '',
  category TEXT NOT NULL DEFAULT 'General',
  unit TEXT NOT NULL DEFAULT 'ea',
  created_at INTEGER NOT NULL
, `department` text DEFAULT 'Other' NOT NULL, `avg_cost_cents` integer DEFAULT 0 NOT NULL, `last_cost_cents` integer DEFAULT 0 NOT NULL, `price_count` integer DEFAULT 0 NOT NULL, `last_vendor` text DEFAULT '' NOT NULL, `last_priced_at` text DEFAULT '' NOT NULL);
CREATE TABLE locations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'warehouse',
  assigned_to TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL
);
CREATE TABLE stock_levels (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  part_id INTEGER NOT NULL,
  location_id INTEGER NOT NULL,
  quantity INTEGER NOT NULL DEFAULT 0,
  min_qty INTEGER NOT NULL DEFAULT 2
);
CREATE TABLE orders (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  vendor TEXT NOT NULL,
  po_number TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'ordered',
  eta TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE order_lines (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  order_id INTEGER NOT NULL,
  part_id INTEGER,
  part_name TEXT NOT NULL,
  sku TEXT NOT NULL DEFAULT '',
  qty INTEGER NOT NULL DEFAULT 1,
  received_qty INTEGER NOT NULL DEFAULT 0,
  unit_cost_cents INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE staging_jobs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  customer TEXT NOT NULL,
  job_type TEXT NOT NULL DEFAULT 'Service',
  job_date TEXT NOT NULL DEFAULT '',
  truck_location_id INTEGER,
  status TEXT NOT NULL DEFAULT 'needed',
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL
);
CREATE TABLE staging_lines (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  staging_id INTEGER NOT NULL,
  part_id INTEGER,
  part_name TEXT NOT NULL,
  qty INTEGER NOT NULL DEFAULT 1,
  pulled INTEGER NOT NULL DEFAULT 0,
  source_location_id INTEGER
);
CREATE TABLE tech_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tech_name TEXT NOT NULL,
  part_description TEXT NOT NULL,
  qty INTEGER NOT NULL DEFAULT 1,
  urgency TEXT NOT NULL DEFAULT 'normal',
  job_ref TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'new',
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL
, image_blob_key TEXT NOT NULL DEFAULT '', ai_part_name TEXT NOT NULL DEFAULT '', ai_equipment TEXT NOT NULL DEFAULT '', ai_confidence TEXT NOT NULL DEFAULT '', ai_notes TEXT NOT NULL DEFAULT '');
CREATE TABLE intake_verifications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  order_id INTEGER,
  vendor TEXT NOT NULL DEFAULT '',
  po_number TEXT NOT NULL DEFAULT '',
  checked_by TEXT NOT NULL DEFAULT '',
  verdict TEXT NOT NULL DEFAULT 'unclear',
  confidence TEXT NOT NULL DEFAULT '',
  invoice_blob_key TEXT NOT NULL DEFAULT '',
  part_blob_key TEXT NOT NULL DEFAULT '',
  invoice_vendor TEXT NOT NULL DEFAULT '',
  invoice_po_number TEXT NOT NULL DEFAULT '',
  invoice_parts TEXT NOT NULL DEFAULT '',
  physical_part TEXT NOT NULL DEFAULT '',
  summary TEXT NOT NULL DEFAULT '',
  discrepancies TEXT NOT NULL DEFAULT '',
  recommended_action TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL
);
CREATE TABLE equipment (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT 'Tool',
  serial_number TEXT NOT NULL DEFAULT '',
  asset_tag TEXT NOT NULL DEFAULT '',
  brand_model TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'available',
  condition TEXT NOT NULL DEFAULT 'good',
  current_location_id INTEGER,
  assigned_to TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
, is_consigned INTEGER NOT NULL DEFAULT 0, consignment_owner TEXT NOT NULL DEFAULT '', consignment_email TEXT NOT NULL DEFAULT '', consignment_value_cents INTEGER NOT NULL DEFAULT 0, consignment_notes TEXT NOT NULL DEFAULT '');
CREATE TABLE equipment_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  equipment_id INTEGER NOT NULL,
  action TEXT NOT NULL DEFAULT 'transfer',
  from_location_id INTEGER,
  to_location_id INTEGER,
  performed_by TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL
, equipment_name TEXT NOT NULL DEFAULT '', equipment_removed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE consignment_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  equipment_id INTEGER NOT NULL,
  owner TEXT NOT NULL DEFAULT '',
  notify_email TEXT NOT NULL DEFAULT '',
  from_location_id INTEGER,
  to_location_id INTEGER,
  action TEXT NOT NULL DEFAULT 'transfer',
  performed_by TEXT NOT NULL DEFAULT '',
  notes TEXT NOT NULL DEFAULT '',
  job_ref TEXT NOT NULL DEFAULT '',
  email_status TEXT NOT NULL DEFAULT 'pending',
  email_sent_at TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL
, email_subject TEXT NOT NULL DEFAULT '', email_body TEXT NOT NULL DEFAULT '', email_attempts INTEGER NOT NULL DEFAULT 0, email_queued_at TEXT NOT NULL DEFAULT '', email_last_error TEXT NOT NULL DEFAULT '', equipment_name TEXT NOT NULL DEFAULT '', serial_number TEXT NOT NULL DEFAULT '', asset_tag TEXT NOT NULL DEFAULT '', equipment_removed INTEGER NOT NULL DEFAULT 0);
DELETE FROM sqlite_sequence;
COMMIT;
